17		"github.com/entireio/cli/cmd/entire/cli/settings"
18	)
19	
20	// CheckpointTokenEnvVar is the environment variable for providing an access token
21	// used to authenticate git push/fetch operations for checkpoint branches.
22	// The token is injected as an HTTP Basic Authorization header per RFC 7617:
23	// the credentials string "x-access-token:<token>" is base64-encoded and sent as
24	// "Authorization: Basic <base64>". This matches GitHub's token auth for Git HTTPS.
25	// SSH remotes ignore the token (with a warning).
26	const CheckpointTokenEnvVar = "ENTIRE_CHECKPOINT_TOKEN"
27	
28	var sshTokenWarningOnce sync.Once //nolint:gochecknoglobals // intentional per-process gate
29	
30	// FetchOptions configures a git fetch operation.
31	type FetchOptions struct {
32		Remote   string   // remote name or URL (required)
33		RefSpecs []string // one or more refspecs / object hashes
34		NoTags   bool     // adds --no-tags
35		NoFilter bool     // when true, skips --filter=blob:none even if filtered fetches are enabled
36		// Shallow adds --depth=1 to fetch only the tip commit and its tree. Use
37		// for tip-only probes (e.g. resolving the latest checkpoint metadata)
38		// where ancestry isn't needed. Creates .git/shallow state — callers that
39		// later require full history should opt into Unshallow on a follow-up
40		// fetch.
41		Shallow bool
42		// Unshallow adds --unshallow when the repository is currently shallow,
43		// triggering git to download the rest of the history for the fetched ref.
44		// Set this on metadata-repair / reconcile paths that need complete
45		// checkpoint ancestry. Do not set on generic branch fetches — it would
46		// silently convert a deliberately-shallow user clone into a full one.
47		Unshallow bool
48		Dir       string   // working directory (empty = CWD)
49		ExtraArgs []string // additional flags before remote (e.g., "--no-write-fetch-head")
50	}
51	
52	// Fetch runs git fetch with checkpoint token injection and optional
53	// filtered fetches (--filter=blob:none when settings enable it).
54	// GIT_TERMINAL_PROMPT=0 is always set.
55	//
56	// Callers that pass a remote name (e.g., "origin") and want filtered fetches to
57	// resolve the name to a URL (to avoid persisting promisor settings) should call
58	// ResolveFetchTarget first and pass the resolved target as opts.Remote.
59	func Fetch(ctx context.Context, opts FetchOptions) ([]byte, error) {
60		args := []string{"fetch", "--no-auto-gc"}
61		if opts.NoTags {
62			args = append(args, "--no-tags")
63		}
64		args = append(args, opts.ExtraArgs...)
65		switch {
66		case opts.Shallow:
67			args = append(args, "--depth=1")
68		case opts.Unshallow && isShallowRepository(ctx, opts.Dir):
69			args = append(args, "--unshallow")
70		}
71		if !opts.NoFilter && settings.IsFilteredFetchesEnabled(ctx) {
72			args = append(args, "--filter=blob:none")
73		}
74		args = append(args, opts.Remote)
75		args = append(args, opts.RefSpecs...)
76	
77		cmd := newCommand(ctx, args...)
78		if opts.Dir != "" {
79			cmd.Dir = opts.Dir
80		}
81		disableTerminalPrompt(cmd)
82		out, err := cmd.CombinedOutput()
83		if err != nil {
84			return out, fmt.Errorf("git fetch: %w", err)
85		}
86		return out, nil
87	}
88	
89	// FetchBlobs fetches specific objects (typically blobs) by hash from a remote.
90	// Uses `git fetch-pack` rather than `git fetch` because the high-level
91	// porcelain enforces partial-clone integrity checks that reject blob-only
92	// responses with "did not send all necessary objects". Plumbing skips those
93	// checks — it just downloads the requested objects into .git/objects/pack
94	// and exits — which is exactly what we want when grabbing individual blobs
95	// by SHA. Works against GitHub for any reachable object, including blobs.
96	//
97	// The remote should be a URL (not a remote name) to avoid persisting promisor
98	// settings onto the named remote. Use FetchURL to obtain the URL.
99	func FetchBlobs(ctx context.Context, remote string, hashes []string) error {
100		args := []string{"fetch-pack", remote}
101		args = append(args, hashes...)
102	
103		cmd := newCommand(ctx, args...)
104		disableTerminalPrompt(cmd)
105		output, err := cmd.CombinedOutput()
106		if err != nil {
107			redactedURL := RedactURL(remote)
108			msg := strings.TrimSpace(strings.ReplaceAll(string(output), remote, redactedURL))
109			if msg != "" {
110				return fmt.Errorf("git fetch-pack from %s: %s: %w", redactedURL, msg, err)
111			}
112			return fmt.Errorf("git fetch-pack from %s: %w", redactedURL, err)
113		}
114		return nil
115	}
116	
117	// CatFilesOptions configures a git cat-file --batch read.
118	type CatFilesOptions struct {
119		Specs     []string // one or more object names or revspecs
120		Dir       string   // working directory (empty = CWD)
121		ExtraArgs []string // additional flags before --batch
122	}
123	
124	// CatFileResult is the result of reading one cat-file batch spec.
125	type CatFileResult struct {
126		Content []byte
127		Missing bool
128		Err     error
129	}
130	
131	// CatFiles reads specs through git cat-file --batch.
132	func CatFiles(ctx context.Context, opts CatFilesOptions) map[string]CatFileResult {
133		specs := uniqueStrings(opts.Specs)
134		results := make(map[string]CatFileResult, len(specs))
135		if len(specs) == 0 {
136			return results
137		}
138	
139		args := []string{"cat-file"}
140		args = append(args, opts.ExtraArgs...)
141		args = append(args, "--batch")
142		cmd := newCommand(ctx, args...)
143		if opts.Dir != "" {
144			cmd.Dir = opts.Dir
145		}
146		cmd.Stdin = strings.NewReader(strings.Join(specs, "\n") + "\n")
147		disableTerminalPrompt(cmd)
148		var stderr bytes.Buffer
149		cmd.Stderr = &stderr
150	
151		output, err := cmd.Output()
152		if err != nil {
153			wrapped := catFilesError(err, stderr.String())
154			for _, spec := range specs {
155				results[spec] = CatFileResult{Err: wrapped}
156			}
157			return results
158		}
159	
160		reader := bufio.NewReader(bytes.NewReader(output))
161		for i, spec := range specs {
162			result, parseErr := parseBlobBatchEntry(reader)
163			if parseErr != nil {
164				for _, s := range specs[i:] {
165					results[s] = CatFileResult{Err: parseErr}
166				}
167				break
168			}
169			results[spec] = result
170		}
171		return results
172	}
173	
174	func parseBlobBatchEntry(reader *bufio.Reader) (CatFileResult, error) {
175		header, err := reader.ReadString('\n')
176		if err != nil {
177			return CatFileResult{}, fmt.Errorf("parse git cat-file batch: %w", err)
178		}
179		header = strings.TrimSuffix(header, "\n")
180	
181		fields := strings.Fields(header)
182		if len(fields) == 2 && fields[1] == "missing" {
183			return CatFileResult{Missing: true}, nil
184		}
185		if len(fields) != 3 {
186			return CatFileResult{}, fmt.Errorf("parse git cat-file batch: unexpected header %q", header)
187		}
188	
189		size, err := strconv.ParseInt(fields[2], 10, 64)
190		if err != nil {
191			return CatFileResult{}, fmt.Errorf("parse git cat-file batch: invalid size %q: %w", fields[2], err)
192		}
193		content := make([]byte, size)
194		if _, err := io.ReadFull(reader, content); err != nil {
195			return CatFileResult{}, fmt.Errorf("parse git cat-file batch: %w", err)
196		}
197		separator, err := reader.ReadByte()
198		if err != nil {
199			return CatFileResult{}, fmt.Errorf("parse git cat-file batch: %w", err)
200		}
201		if separator != '\n' {
202			return CatFileResult{}, fmt.Errorf("parse git cat-file batch: unexpected separator %q", separator)
203		}
204	
205		if fields[1] != "blob" {
206			return CatFileResult{Err: fmt.Errorf("object %s is %s, want blob", fields[0], fields[1])}, nil
207		}
208		return CatFileResult{Content: content}, nil
209	}
210	
211	func catFilesError(err error, stderr string) error {
212		msg := strings.TrimSpace(stderr)
213		if msg == "" {
214			return fmt.Errorf("git cat-file --batch: %w", err)
215		}
216		return fmt.Errorf("git cat-file --batch: %s: %w", msg, err)
217	}
218	
219	func uniqueStrings(values []string) []string {
220		seen := make(map[string]struct{}, len(values))
221		unique := make([]string, 0, len(values))
222		for _, value := range values {
223			if value == "" {
224				continue
225			}
226			if _, ok := seen[value]; ok {
227				continue
228			}
229			seen[value] = struct{}{}
230			unique = append(unique, value)
231		}
232		return unique
233	}
234	
235	// PushResult holds raw porcelain output from git push.
236	type PushResult struct {
237		Output string
238	}
239	
240	// PushOptions configures a git push operation.
241	type PushOptions struct {
242		Remote    string
243		RefSpecs  []string
244		ExtraArgs []string // additional flags before remote
245		Dir       string
246	}
247	
248	// Push runs git push --no-verify --porcelain with token injection.
249	// GIT_TERMINAL_PROMPT=0 is always set.
250	func Push(ctx context.Context, remote, refSpec string) (PushResult, error) {
251		return PushWithOptions(ctx, PushOptions{
252			Remote:   remote,
253			RefSpecs: []string{refSpec},
254		})
255	}
256	
257	// PushWithOptions runs git push --no-verify --porcelain with token injection.
258	// GIT_TERMINAL_PROMPT=0 is always set.
259	func PushWithOptions(ctx context.Context, opts PushOptions) (PushResult, error) {
260		pushTarget, err := resolvePushCommandTarget(ctx, opts.Remote)
261		if err != nil {
262			return PushResult{}, fmt.Errorf("resolve push target: %w", err)
263		}
264	
265		args := []string{"push", "--no-verify", "--porcelain"}
266		args = append(args, opts.ExtraArgs...)
267		args = append(args, pushTarget)
268		args = append(args, opts.RefSpecs...)
269	
270		cmd := newCommand(ctx, args...)
271		if opts.Dir != "" {
272			cmd.Dir = opts.Dir
273		}
274		disableTerminalPrompt(cmd)
275		output, err := cmd.CombinedOutput()
276		if err != nil {
277			return PushResult{Output: string(output)}, fmt.Errorf("git push: %w", err)
278		}
279		return PushResult{Output: string(output)}, nil
280	}
281	
282	// LsRemote runs git ls-remote with token injection.
283	// GIT_TERMINAL_PROMPT=0 is always set. Returns stdout only.
284	func LsRemote(ctx context.Context, remote string, patterns ...string) ([]byte, error) {
285		return lsRemote(ctx, "", remote, patterns...)
286	}
287	
288	// LsRemoteInDir is like LsRemote but runs in a specific directory.
289	func LsRemoteInDir(ctx context.Context, dir, remote string, patterns ...string) ([]byte, error) {
290		return lsRemote(ctx, dir, remote, patterns...)
291	}
292	
293	func lsRemote(ctx context.Context, dir, remote string, patterns ...string) ([]byte, error) {
294		args := append([]string{"ls-remote", remote}, patterns...)
295		cmd := newCommand(ctx, args...)
296		if dir != "" {
297			cmd.Dir = dir
298		}
299		disableTerminalPrompt(cmd)
300		out, err := cmd.Output()
301		if err != nil {
302			return out, fmt.Errorf("git ls-remote: %w", err)
303		}
304		return out, nil
305	}
306	
307	// IsURL returns true if the target looks like a URL rather than a git remote name.
308	func IsURL(target string) bool {
309		return strings.Contains(target, "://") || strings.Contains(target, "@")
310	}
311	
312	// ResolveFetchTarget returns the git fetch target to use. When filtered
313	// fetches are enabled, configured remotes are resolved to their URL so git does
314	// not persist promisor settings onto the remote name.
315	func ResolveFetchTarget(ctx context.Context, target string) (string, error) {
316		if IsURL(target) || isLocalPath(target) || !settings.IsFilteredFetchesEnabled(ctx) {
317			return target, nil
318		}
319		url, err := GetRemoteURL(ctx, target)
320		if err != nil {
321			return "", fmt.Errorf("get remote URL: %w", err)
322		}
323		return url, nil
324	}
325	
326	// isShallowRepository returns true when the git repository at dir is shallow.
327	// An empty dir inherits the parent process's working directory, matching the
328	// semantics callers use when invoking Fetch with empty FetchOptions.Dir.
329	func isShallowRepository(ctx context.Context, dir string) bool {
330		cmd := exec.CommandContext(ctx, "git", "rev-parse", "--is-shallow-repository")
331		cmd.Dir = dir
332		disableTerminalPrompt(cmd)
333		out, err := cmd.Output()
334		if err != nil {
335			return false
336		}
337		return strings.TrimSpace(string(out)) == "true"
338	}
339	
340	// newCommand creates an exec.Cmd for a git operation that may need
341	// checkpoint token authentication. If ENTIRE_CHECKPOINT_TOKEN is set:
342	//   - if the target in args is (or resolves to) an SSH remote, the target is
343	//     rewritten in the args to the equivalent HTTPS URL so git uses HTTP
344	//     transport and our injected Authorization header applies;
345	//   - a Basic auth token is then injected via GIT_CONFIG_COUNT/GIT_CONFIG_KEY_*/
346	//     GIT_CONFIG_VALUE_* environment variables.
347	//
348	// If rewriting fails (unparseable URL, missing owner/repo) the command runs
349	// unmodified and a one-shot warning is printed.
350	// For empty/unset tokens, the command is returned unmodified.
351	//
352	// The remote is extracted from args by skipping the git subcommand and any flags
353	// (arguments starting with "-"). For example, in
354	// ["push", "--no-verify", "origin", "main"], the remote is "origin".
355	func newCommand(ctx context.Context, args ...string) *exec.Cmd {
356		token := strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar))
357	
358		mkCmd := func(finalArgs []string) *exec.Cmd {
359			c := exec.CommandContext(ctx, "git", finalArgs...)
360			c.Stdin = nil // Disconnect stdin to prevent hanging in hook context
361			return c
362		}
363	
364		if token == "" {
365			return mkCmd(args)
366		}
367	
368		if !isValidToken(token) {
369			fmt.Fprintf(os.Stderr, "[entire] Warning: %s contains invalid characters (CR, LF, or other control chars) — token ignored\n", CheckpointTokenEnvVar)
370			return mkCmd(args)
371		}
372	
373		target := extractRemoteFromArgs(args)
374		if target == "" {
375			return mkCmd(args)
376		}
377	
378		newTarget, protocol := resolveTargetForTokenAuth(ctx, target)
379		if newTarget != target {
380			args = replaceFirstPositional(args, newTarget)
381		}
382	
383		cmd := mkCmd(args)
384	
385		switch protocol {
386		case ProtocolSSH:
387			sshTokenWarningOnce.Do(func() {
388				fmt.Fprintf(os.Stderr, "[entire] Warning: %s is set but remote uses SSH — token ignored for SSH remotes\n", CheckpointTokenEnvVar)
389			})
390			return cmd
391		case ProtocolHTTPS:
392			cmd.Env = appendCheckpointTokenEnv(os.Environ(), token)
393			return cmd
394		default:
395			// Unknown protocol (e.g., local path, or resolution failed) — don't inject
396			return cmd
397		}
398	}
399	
400	// resolveTargetForTokenAuth resolves a git target (remote name or URL) to its
401	// effective protocol, rewriting SSH targets to the equivalent HTTPS URL so
402	// token-based auth can be applied. Returns the (possibly rewritten) target and
403	// its final protocol. Protocol is "" when resolution fails (local path,
404	// nonexistent remote, unparseable URL).
405	//
406	// This is only meaningful when ENTIRE_CHECKPOINT_TOKEN is set; callers gate on
407	// that themselves.
408	func resolveTargetForTokenAuth(ctx context.Context, target string) (string, string) {
409		if target == "" || isLocalPath(target) {
410			return target, ""
411		}
412	
413		rawURL := target
414		if !IsURL(target) {
415			var err error
416			rawURL, err = GetRemoteURL(ctx, target)
417			if err != nil {
418				return target, ""
419			}
420		}
421	
422		info, err := ParseURL(rawURL)
423		if err != nil {
424			return target, ""
425		}
426	
427		if info.Protocol == ProtocolSSH {
428			if httpsURL, ok := deriveTokenOriginURL(rawURL); ok {
429				return httpsURL, ProtocolHTTPS
430			}
431			return target, ProtocolSSH
432		}
433	
434		return target, info.Protocol
435	}
436	
437	// replaceFirstPositional returns a copy of args with the first non-flag
438	// argument after args[0] (the git subcommand) replaced by newTarget. Callers
439	// use this to rewrite a remote name/URL after resolution without mutating the
440	// original slice.
441	func replaceFirstPositional(args []string, newTarget string) []string {
442		out := make([]string, len(args))
443		copy(out, args)
444		for i := 1; i < len(out); i++ {
445			if !strings.HasPrefix(out[i], "-") {
446				out[i] = newTarget
447				return out
448			}
449		}
450		return out
451	}
452	
453	// extractRemoteFromArgs finds the remote URL or name from git command args.
454	// It skips the subcommand (first arg) and any flags (args starting with "-"),
455	// returning the first positional argument, which is the remote for push/fetch/ls-remote.
456	func extractRemoteFromArgs(args []string) string {
457		if len(args) < 2 {
458			return ""
459		}
460		// Skip subcommand (e.g., "push", "fetch", "ls-remote").
461		for _, arg := range args[1:] {
462			if !strings.HasPrefix(arg, "-") {
463				return arg
464			}
465		}
466		return ""
467	}
468	
469	// appendCheckpointTokenEnv appends GIT_CONFIG_COUNT-based env vars to inject
470	// an Authorization header into git HTTP requests. The token is sent as a Basic
471	// credential with the format "x-access-token:<token>" (base64-encoded), which
472	// is compatible with GitHub's token authentication.
473	//
474	// Existing GIT_CONFIG_KEY_*/GIT_CONFIG_VALUE_* entries are preserved; the new
475	// http.extraHeader entry is appended at the next free index and
476	// GIT_CONFIG_COUNT is updated accordingly. This keeps caller-injected git
477	// config (e.g., safe.directory, custom CA settings) intact.
478	func appendCheckpointTokenEnv(baseEnv []string, token string) []string {
479		existingCount := 0
480		for _, e := range baseEnv {
481			rest, ok := strings.CutPrefix(e, "GIT_CONFIG_COUNT=")
482			if !ok {
483				continue
484			}
485			if n, err := strconv.Atoi(rest); err == nil && n > 0 {
486				existingCount = n
487			}
488		}
489	
490		// Strip the old GIT_CONFIG_COUNT entry (we'll emit a new one) but keep
491		// GIT_CONFIG_KEY_*/GIT_CONFIG_VALUE_* entries in place.
492		filtered := make([]string, 0, len(baseEnv)+3)
493		for _, e := range baseEnv {
494			if strings.HasPrefix(e, "GIT_CONFIG_COUNT=") {
495				continue
496			}
497			filtered = append(filtered, e)
498		}
499	
500		idx := existingCount
501		encoded := base64.StdEncoding.EncodeToString([]byte("x-access-token:" + token))
502		return append(filtered,
503			fmt.Sprintf("GIT_CONFIG_COUNT=%d", existingCount+1),
504			fmt.Sprintf("GIT_CONFIG_KEY_%d=http.extraHeader", idx),
505			fmt.Sprintf("GIT_CONFIG_VALUE_%d=Authorization: Basic %s", idx, encoded),
506		)
507	}
508	
509	// isValidToken returns false if the token contains control characters (bytes < 0x20
510	// or 0x7F). This prevents HTTP header injection via CR/LF or other control chars
511	// embedded in the token value.
512	func isValidToken(token string) bool {
513		for _, b := range []byte(token) {
514			if b < 0x20 || b == 0x7F {
515				return false
516			}
517		}
518		return true
519	}
520	
521	// resolvePushCommandTarget returns the target to pass to git push. When a
522	// dedicated checkpoint_remote is configured, the checkpoint URL is returned so
523	// the push is routed to the separate checkpoint repo. Otherwise the remote
524	// name is returned unchanged so git uses its own config, updates the
525	// refs/remotes/<name>/<branch> tracking ref, and subsequent calls can use that
526	// tracking ref to skip redundant pushes.
527	//
528	// SSH→HTTPS coercion for token auth is handled by newCommand, which rewrites
529	// the command args or injects per-host config, rather than being baked into
530	// the target here.
531	func resolvePushCommandTarget(ctx context.Context, target string) (string, error) {
532		if target == "" || IsURL(target) || isLocalPath(target) {
533			return target, nil
534		}
535	
536		pushTarget, enabled, err := PushURL(ctx, target)
537		if err != nil {
538			return "", err
539		}
540		if !enabled || pushTarget == "" {
541			return target, nil
542		}
543		return pushTarget, nil
544	}
545	
546	func isLocalPath(target string) bool {
547		return filepath.IsAbs(target) || strings.HasPrefix(target, "./") || strings.HasPrefix(target, "../")
548	}
549	
550	// disableTerminalPrompt sets GIT_TERMINAL_PROMPT=0 on the command,
551	// initializing cmd.Env from os.Environ() if nil.
552	func disableTerminalPrompt(cmd *exec.Cmd) {
553		if cmd.Env == nil {
554			cmd.Env = os.Environ()
555		}
556		cmd.Env = append(cmd.Env, "GIT_TERMINAL_PROMPT=0")
557	}
