//go:build unix

package remote

import (
	"context"
	"syscall"
	"testing"
	"time"
)

func TestSetProcessGroupKill_SetsSetpgidAndCancel(t *testing.T) {
	t.Parallel()

	cmd := newCommand(context.Background(), "push", "origin", "main")

	if cmd.SysProcAttr == nil || !cmd.SysProcAttr.Setpgid {
		t.Error("Setpgid = false; want true so the whole process group can be killed")
	}
	if cmd.Cancel == nil {
		t.Fatal("Cancel = nil; want a group-kill handler")
	}
}

// TestHardenSubprocess_KillsProcessGroup proves the fix end-to-end: a child that
// backgrounds a grandchild which inherits (and holds open) the output pipe must
// still be terminated when the context is cancelled. Without group-kill, the
// backgrounded `sleep` keeps the pipe open and CombinedOutput blocks for the full
// 60s; with it, the whole group dies and CombinedOutput returns promptly.
func TestHardenSubprocess_KillsProcessGroup(t *testing.T) {
	t.Parallel()

	ctx, cancel := context.WithTimeout(context.Background(), 300*time.Millisecond)
	defer cancel()

	// `sleep 60 &` backgrounds a grandchild holding stdout; `wait` keeps the
	// shell (the group leader) alive so only a group-wide kill terminates both.
	cmd := exec.CommandContext(ctx, "/bin/sh", "-c", "sleep 60 & wait")
	hardenSubprocess(cmd)

	start := time.Now()
	_, _ = cmd.CombinedOutput()
	elapsed := time.Since(start)

	// Group-kill closes the pipe immediately on cancellation, so this returns in
	// well under the 60s sleep (and under the 10s WaitDelay backstop too).
	if elapsed > 5*time.Second {
		t.Fatalf("CombinedOutput took %v; group-kill did not terminate the pipe-holding grandchild", elapsed)
	}
}

// Guard against the negative-PID group-kill being silently dropped: ESRCH is
// tolerated, but a missing handler is not.
func TestSetProcessGroupKill_CancelIsGroupKill(t *testing.T) {
	t.Parallel()

	cmd := exec.CommandContext(context.Background(), "/bin/sh", "-c", "sleep 60 & wait")
	setProcessGroupKill(cmd)
	if err := cmd.Start(); err != nil {
		t.Fatalf("start: %v", err)
	}
	t.Cleanup(func() { _ = cmd.Wait() })

	if err := cmd.Cancel(); err != nil {
		t.Fatalf("Cancel returned %v; want nil", err)
	}
	// The group should now be gone; a second kill must report ESRCH.
	if err := syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL); err != syscall.ESRCH {
		t.Errorf("second group kill err = %v; want ESRCH (group already terminated)", err)
	}
}

